# Хэлперы
def h(p, content, bbox, level=2, extra=None):
    b = {'type': 'heading', 'page number': p, 'heading level': level, 'content': content, 'bounding box': bbox}
    if extra: b.update(extra)
    return b

def par(p, content, bbox):
    return {'type': 'paragraph', 'page number': p, 'content': content, 'bounding box': bbox}

def li(p, items, bbox, ltype='bullet'):
    return {'type': 'list', 'page number': p, 'list_type': ltype,
            'content': '\n'.join(items),
            'items': [{'content': it} for it in items],
            'bounding box': bbox}

def table(p, rows, bbox):
    r = []
    for cells in rows:
        r.append({'cells': [{'block': [{'type': 'paragraph', 'content': c}]} for c in cells]})
    return {'type': 'table', 'page number': p, 'rows': r, 'bounding box': bbox}

def img(p, key, bbox):
    return {'type': 'image', 'page number': p, 'content': '', 'image_key': key, 'bounding box': bbox}

def formula(p, content, bbox, latex=''):
    return {'type': 'formula', 'page number': p, 'content': content, 'latex': latex, 'bounding box': bbox}

