PAGES[11] = [
    h(11, '2.4 МАТЕРИАЛЫ', [260.0, 99.5, 354.3, 111.8], 2),
    par(11, '2.4.1 Качество и основные характеристики материалов, применяемых для изготовления деталей, узлов и крепежа холодильного оборудования, работающих в условиях динамических нагрузок, избыточного давления, переменных и низких температур, должны отвечать требованиям части XIII «Материалы».', [99.4, 124.1, 536.3, 174.3]),
    par(11, 'Выбор материала должен производиться в зависимости от рабочей температуры и физико-химических свойств холодильного агента:', [99.4, 174.6, 536.3, 199.6]),
    li(11, [
        '.1 материалы частей оборудования, работающих с холодильными агентами, смазочными маслами и их сочетаниями, а также охлаждающими и охлаждаемыми средами, должны быть инертны и устойчивы по отношению к ним;',
        '.2 материалы частей оборудования, работающих в условиях низких температур, не должны иметь структурных необратимых изменений и должны сохранять достаточную прочность при низких рабочих температурах;',
        '.3 материалы для деталей и узлов холодильного оборудования, работающих при низких температурах, должны выбираться с учетом 1.2 части II «Корпус» и 3.5 части XIII «Материалы».',
        '2.4.2 Детали механизмов и аппаратов, которые соприкасаются со средами, способствующими возникновению коррозии, должны быть изготовлены из материалов с достаточной коррозионной стойкостью по отношению к этим средам или должны иметь антикоррозионные покрытия.',
    ], [99.4, 199.9, 536.3, 364.0]),
    par(11, 'Узлы и конструкции механизмов и аппаратов, которые изготовлены из материалов с различным электролитическим потенциалом и могут соприкасаться с морской водой, должны быть защищены от контактной коррозии.', [99.4, 364.5, 536.3, 402.0]),
    li(11, [
        '2.4.3 Стальные трубопроводы холодильного агента, холодоносителя и соединительные части этих трубопроводов, изготовленные не из нержавеющей стали, должны быть оцинкованы снаружи или должны иметь равноценную антикоррозионную защиту. Поверхности, соприкасающиеся с холодильным агентом или холодоносителем, не должны быть оцинкованными.',
    ], [99.4, 402.4, 536.2, 465.2]),
    par(11, 'При изготовлении трубопроводов должны быть учтены требования 2.4.1 и 2.4.2.', [99.4, 465.6, 516.6, 477.9]),
]

